-- Publishes the finished articles (author: VARI Studio). Generated by scripts/blog-seed/drafts-to-sql.py --publish.
-- Updates the drafts inserted earlier (matched by English slug) or creates them. Safe to re-run.
-- Every language version in the files is published (ready) and appears on the site for each language that is switched on.

-- Virtual Staging: What It Costs, What It Achieves and the Rules for 2026  (en, de, es, tr)
do $do$
declare pid uuid;
